style.css:
@-moz-document domain("nitrotype.com") {
/* ---------------------------------- */
    /* 1. ROOT COLORS (Custom Properties) */
    /* ---------------------------------- */
    :root {
        --nt-bg-dark: #0a0e14; /* Very Dark Charcoal Blue */
        --nt-accent-blue: #00FFFF; /* Electric Cyan/Lightning Color */
        --nt-text-light: #e0f7ff; /* Light, slightly blue-tinted white */
        --nt-card-bg: #141b26; /* Darker Card Background */
    }

    /* ---------------------------------- */
    /* 2. GLOBAL BACKGROUND & TEXT COLOR */
    /* ---------------------------------- */
    body, html, .page-wrapper, .race-layout-wrapper {
        background-color: var(--nt-bg-dark) !important;
        color: var(--nt-text-light) !important;
    }

    /* Set general text, links, and headings to the light color */
    h1, h2, h3, p, span, a, div {
        color: var(--nt-text-light) !important;
    }

    /* ---------------------------------- */
    /* 3. HEADER & NAVIGATION */
    /* ---------------------------------- */
    .header {
        background-color: var(--nt-card-bg) !important;
        border-bottom: 2px solid var(--nt-accent-blue) !important;
        box-shadow: 0 0 15px rgba(0, 255, 255, 0.5) !important; /* Glow Effect */
    }

    /* ---------------------------------- */
    /* 4. RACE TRACK & CONTENT AREA */
    /* ---------------------------------- */

    /* Main racing container/background */
    .race-screen, .card, .profile-card, .garage-card, .leaderboard-card {
        background-color: var(--nt-card-bg) !important;
        border-radius: 12px !important;
        box-shadow: 0 0 20px rgba(0, 255, 255, 0.2) inset !important;
        border: 1px solid rgba(0, 255, 255, 0.4);
    }

    /* The text paragraph to be typed */
    .dash-text-text {
        font-family: 'Consolas', 'Courier New', monospace !important;
        font-size: 20px !important;
        line-height: 1.6 !important;
        color: #ccc !important;
    }

    /* Typed/finished text color (Correct) */
    .is-correct {
        color: #88ff88 !important; /* Bright green for correct */
    }

    /* Incorrect text color and styling (Lightning error) */
    .is-incorrect {
        color: #ff6666 !important; /* Light red for error */
        background-color: #3d0505 !important;
        text-decoration: underline wavy #ff0000 1px;
    }

    /* Next word to type */
    .currentword {
        color: var(--nt-accent-blue) !important;
        text-shadow: 0 0 8px rgba(0, 255, 255, 0.8);
    }

    /* ---------------------------------- */
    /* 5. TYPING INPUT FIELD */
    /* ---------------------------------- */
    .txtInput {
        background-color: #2c3a4d !important;
        border: 3px solid var(--nt-accent-blue) !important;
        box-shadow: 0 0 10px var(--nt-accent-blue) !important;
        color: var(--nt-text-light) !important;
        border-radius: 8px;
        padding: 15px;
        transition: all 0.2s ease;
    }
    .txtInput:focus {
         box-shadow: 0 0 25px var(--nt-accent-blue), 0 0 5px #fff !important;
    }

    /* ---------------------------------- */
    /* 6. BUTTONS AND UI ACTIONS */
    /* ---------------------------------- */
    .btn, button {
        /* Bright, "charged" look */
        background: linear-gradient(135deg, #00FFFF, #00CCFF) !important;
        color: var(--nt-bg-dark) !important; /* Dark text on bright button */
        border: none !important;
        border-radius: 6px;
        text-shadow: none;
        box-shadow: 0 4px 15px rgba(0, 255, 255, 0.4);
        transition: transform 0.1s, box-shadow 0.1s;
    }

    .btn:hover, button:hover {
        transform: translateY(-2px);
        box-shadow: 0 6px 20px rgba(0, 255, 255, 0.8); /* Stronger glow on hover */
        background: linear-gradient(135deg, #33FFFF, #33DDFF) !important;
    }
}
